30	import org.springframework.http.HttpInputMessage;
31	import org.springframework.http.HttpStatus;
32	import org.springframework.http.ResponseEntity;
33	import org.springframework.http.converter.HttpMessageConverter;
34	import org.springframework.samples.petclinic.model.Owner;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.service.ClinicService;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	import org.springframework.web.servlet.mvc.method.annotation.RequestBodyAdvice;
41	
42	import tools.jackson.databind.JsonNode;
43	import tools.jackson.databind.ObjectMapper;
44	
45	/**
46	 * Rejects a create-owner request whose lastName and address already belong to another owner
47	 * (compared case-insensitively with whitespace collapsed), responding 409 Conflict. The check
48	 * is skipped when the request sets {@code sharesHousehold} to true. Because that flag is not a
49	 * mapped owner field it is read from the raw request body, which is buffered and re-supplied to
50	 * the downstream converter.
51	 */
52	@ControllerAdvice
53	@Order(Ordered.HIGHEST_PRECEDENCE)
54	public class OwnerUniqueHouseholdAdvice implements RequestBodyAdvice {
55	
56	    private final ClinicService clinicService;
57	
58	    private final ObjectMapper objectMapper;
59	
60	    public OwnerUniqueHouseholdAdvice(ClinicService clinicService, ObjectMapper objectMapper) {
61	        this.clinicService = clinicService;
62	        this.objectMapper = objectMapper;
63	    }
64	
65	    @Override
66	    public boolean supports(MethodParameter methodParameter, Type targetType,
67	                            Class<? extends HttpMessageConverter<?>> converterType) {
68	        Method method = methodParameter.getMethod();
69	        return OwnerFieldsDto.class.equals(targetType) && method != null
70	            && "addOwner".equals(method.getName());
71	    }
72	
73	    @Override
74	    public HttpInputMessage beforeBodyRead(HttpInputMessage inputMessage, MethodParameter parameter,
75	                                           Type targetType, Class<? extends HttpMessageConverter<?>> converterType)
76	            throws IOException {
77	        byte[] bytes = inputMessage.getBody().readAllBytes();
78	        JsonNode body = objectMapper.readTree(bytes);
79	        if (!body.path("sharesHousehold").asBoolean(false)
80	                && isHouseholdTaken(body.path("lastName").asString(""), body.path("address").asString(""))) {
81	            throw new DuplicateHouseholdException();
82	        }
83	        return buffered(bytes, inputMessage.getHeaders());
84	    }
85	
86	    private boolean isHouseholdTaken(String lastName, String address) {
87	        String key = normalize(lastName) + '\n' + normalize(address);
88	        for (Owner existing : clinicService.findAllOwners()) {
89	            if (key.equals(normalize(existing.getLastName()) + '\n' + normalize(existing.getAddress()))) {
90	                return true;
91	            }
92	        }
93	        return false;
94	    }
95	
96	    private String normalize(String value) {
97	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
98	    }
99	
100	    private HttpInputMessage buffered(byte[] bytes, HttpHeaders headers) {
101	        return new HttpInputMessage() {
102	            @Override
103	            public InputStream getBody() {
104	                return new ByteArrayInputStream(bytes);
105	            }
106	
107	            @Override
108	            public HttpHeaders getHeaders() {
109	                return headers;
110	            }
111	        };
112	    }
113	
114	    @Override
115	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
116	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
117	        return body;
118	    }
119	
120	    @Override
121	    public Object handleEmptyBody(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
122	                                  Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
123	        return body;
124	    }
125	
126	    @ExceptionHandler(DuplicateHouseholdException.class)
127	    @ResponseBody
128	    public ResponseEntity<Void> handleDuplicateHousehold(DuplicateHouseholdException e) {
129	        return ResponseEntity.status(HttpStatus.CONFLICT).build();
130	    }
131	
132	    /** Signals that an owner with the same lastName and address already exists. */
133	    static class DuplicateHouseholdException extends RuntimeException {
134	    }
135	}
