16	package org.springframework.samples.petclinic.util;
17	
18	/**
19	 * Normalizes telephone numbers to E.164 form.
20	 *
21	 * <p>Spaces, dashes and brackets are stripped. A leading '+' with its country code is
22	 * kept as given; otherwise country code '+61' is assumed and a single leading '0' is
23	 * dropped from the national digits. The result is expected to carry 8 to 15 digits after
24	 * the '+', which callers enforce (Bean Validation / DTO pattern) so an unformattable
25	 * input is rejected with 400. Normalization is idempotent, so a value already in E.164
26	 * form is returned unchanged.
27	 */
28	public final class TelephoneNormalizer {
29	
30	    private TelephoneNormalizer() {
31	    }
32	
33	    /** Return {@code telephone} in E.164 form, or {@code null} when it is {@code null}. */
34	    public static String toE164(String telephone) {
35	        if (telephone == null) {
36	            return null;
37	        }
38	        String digits = telephone.replaceAll("[^0-9+]", "");
39	        if (digits.startsWith("+")) {
40	            return "+" + digits.substring(1).replace("+", "");
41	        }
42	        if (digits.startsWith("0")) {
43	            digits = digits.substring(1);
44	        }
45	        return "+61" + digits;
46	    }
47	}
